This simple Javascript won't do the Bubble magic of only returning unique elements in the output array. You'd need to use a Function node with a bit more script for that: 

// Function to check if two objects are equivalent (for primitive values and simple objects)
function areObjectsEqual(obj1, obj2) {
  return JSON.stringify(obj1) === JSON.stringify(obj2);
}

// Merge arrays and remove duplicates
function mergeUniqueArrays(arr1, arr2) {
  const mergedArray = [...arr1, ...arr2];
  const uniqueArray = [];

  for (let item of mergedArray) {
    // Check if item is already in uniqueArray
    if (!uniqueArray.some(existingItem => areObjectsEqual(existingItem, item))) {
      uniqueArray.push(item);
    }
  }

  return uniqueArray;
}

// Example Usage
const array1 = Inputs.List1 || [];
const array2 = Inputs.List2 || [];

try {
  const mergedArray = mergeUniqueArrays(array1, array2);

  Outputs.MergedArray = mergedArray;
  Outputs.Success();
} catch (error) {
  Outputs.error = error;
  Outputs.Failure();
}

